from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _ledger(data, revision_priority, tax_base):
    mode = data.get("rounding", "floor")

    def rounded(n, d=10000):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        if revision_priority == "sequence_first":
            rank = (seq, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if ident not in winners or rank > winners[ident][0]:
            winners[ident] = (rank, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    versions = {name: sorted(row["version"] for row in packages[name])
                for name in names}
    rows = {name: {row["version"]: row for row in packages[name]}
            for name in names}
    choices = [[-1] + versions[name] for name in names]

    for vector in product(*choices):
        install = dict(zip(names, vector))
        if any(install[n] != -1 and n in pins and install[n] != pins[n]
               for n in names):
            continue
        if any(install[n] in blocked.get(n, []) for n in names if install[n] != -1):
            continue
        ok = True
        for name, bounds in data.get("roots", {}).items():
            v = install[name]
            if v == -1 or not bounds[0] <= v <= bounds[1]:
                ok = False
                break
        if not ok:
            continue

        edges = {n: [] for n in names if install[n] != -1}
        reachable = set()
        pending = list(data.get("roots", {}))
        while pending and ok:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = install[name]
            if version == -1:
                ok = False
                break
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                ov = install[other]
                if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                    ok = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not ok or reachable != {n for n in names if install[n] != -1}:
            continue

        visiting, done = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            visiting.remove(name)
            done.add(name)
            return True
        if not all(acyclic(n) for n in edges):
            continue
        return {"versions": {n: install[n] for n in names if install[n] != -1}}
    return {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda j: (j["start"], j["end"]))
        if any(a["end"] > b["start"]
               for i, a in enumerate(ordered) for b in ordered[i + 1:]):
            continue
        value = sum(job["value"] for job in chosen)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    start, deadline = data["start"], data["deadline"]
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, coupons)
    dist = {initial: start}
    queue = [(start, source, initial_mask, coupons)]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == target and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, left - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                dest = edge["v"]
                new_mask = mask | bit.get(dest, 0)
                next_state = (dest, new_mask, remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, new_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, "sequence_first", "original"),
    "component_02": lambda d: _ledger(d, "revision_first", "discounted"),
    "component_03": lambda d: _ledger(d, "sequence_first", "discounted"),
    "component_04": lambda d: _ledger(d, "revision_first", "original"),
    "component_05": lambda d: _ledger(d, "sequence_first", "original"),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
